// Physics Threads — Day 1
// A multiple-choice problem on Newton's Laws (force & motion),
// designed to challenge common misconceptions among high school students.

#set document(
  title: "Physics Threads — Day 1",
  author: "Physics Threads",
)

// Square-ish page so the post looks good on Threads (Instagram-style 1:1 export).
#set page(
  width: 1080pt,
  height: 1080pt,
  margin: 48pt,
  fill: rgb("#0f1117"),
)

#set text(
  font: ("New Computer Modern", "Liberation Serif"),
  size: 22pt,
  fill: white,
)

// ---------- Header ----------
#align(center)[
  #text(size: 18pt, fill: rgb("#9aa0aa"))[#upper[physics threads · day 1]]

  #v(6pt)

  #text(size: 34pt, weight: "bold", fill: white)[
    Newton's Laws: Force & Motion
  ]

  #v(4pt)
  #line(length: 100%, stroke: 2pt + rgb("#ff4d6d"))
]

#v(14pt)

// ---------- Problem statement ----------
#set par(justify: true, leading: 0.7em)
#text(size: 21pt)[
  Block *A* (mass #text(fill: rgb("#4cc9f0"))[$4 "kg"$) rests on a *frictionless*
  horizontal table. It is connected by a *light, inextensible string* over an
  ideal pulley to block *B* (mass #text(fill: rgb("#f72585"))[$6 "kg"$]) hanging
  vertically. The system is released from rest.

  #v(6pt)
  Take #text(fill: rgb("#ffd166"))[$g = 10 "m/s"^2$].

  *What is the magnitude of the force exerted on the pulley by the string?*
]

#v(10pt)

// ---------- Diagram ----------
#align(center)[
  #cetz.canvas({
    import cetz.draw: *
    set-style(
      stroke: white,
      fill: white,
      stroke-width: 1.6pt,
    )

    // Color palette
    let colA = rgb("#4cc9f0")
    let colB = rgb("#f72585")
    let colTable = rgb("#2a2f3a")
    let colStr = rgb("#ffd166")
    let colT = rgb("#06d6a0")

    // ---- Ground line / table edge ----
    line((0.4, 0), (9.6, 0), stroke: (paint: rgb("#3a3f4a"), thickness: 2pt))
    // Table hatch (vertical lines under table top)
    for x in range(1, 10) {
      line((x * 0.9 + 0.2, 0), (x * 0.9 + 0.2, -0.6),
        stroke: (paint: rgb("#3a3f4a"), thickness: 1pt))
    }

    // ---- Table top (where block A sits) ----
    rect((0.4, 0.05), (6.4, 0.35), fill: colTable, stroke: rgb("#3a3f4a"))

    // ---- Pulley support (ceiling/frame) ----
    line((6.4, 3.6), (6.4, 4.0), stroke: (paint: rgb("#9aa0aa"), thickness: 2pt))
    rect((5.9, 4.0), (6.9, 4.2), fill: rgb("#9aa0aa"), stroke: rgb("#cfd2da"))

    // ---- Pulley ----
    circle((6.4, 3.4), radius: 0.45,
      fill: rgb("#1c1f27"), stroke: (paint: white, thickness: 2pt))
    circle((6.4, 3.4), radius: 0.10,
      fill: rgb("#cfd2da"), stroke: (paint: rgb("#cfd2da"), thickness: 1pt))

    // ---- Block A (on table) ----
    rect((1.4, 0.35), (3.4, 1.85),
      fill: colA.lighten(15%), stroke: (paint: colA, thickness: 2.4pt))
    content(((1.4 + 3.4)/2, (0.35 + 1.85)/2),
      text(size: 26pt, weight: "bold", fill: rgb("#0f1117"))[A])

    // ---- Block B (hanging) ----
    rect((5.4, 1.4), (7.4, 2.9),
      fill: colB.lighten(15%), stroke: (paint: colB, thickness: 2.4pt))
    content(((5.4 + 7.4)/2, (1.4 + 2.9)/2),
      text(size: 26pt, weight: "bold", fill: white)[B])

    // ---- String ----
    // horizontal part (over the table, between A and pulley)
    line((3.4, 1.1), (6.05, 3.1),
      stroke: (paint: colStr, thickness: 2.4pt))
    // vertical part (down from pulley to B)
    line((6.4, 2.95), (6.4, 1.4),
      stroke: (paint: colStr, thickness: 2.4pt))

    // ---- Mass labels ----
    content((2.4, 2.05), text(size: 16pt, fill: colA,
      weight: "bold")[m_A = 4 kg])
    content((8.0, 2.15), text(size: 16pt, fill: colB,
      weight: "bold")[m_B = 6 kg])

    // ---- Tension arrows on string (both sides of pulley) ----
    // horizontal segment: arrow from block A toward pulley
    line((4.1, 1.5), (4.9, 2.1),
      stroke: (paint: colT, thickness: 2pt),
      mark: (end: "stealth", fill: colT, scale: 1.1))
    content((4.0, 1.25), text(size: 14pt, fill: colT, weight: "bold")[T])

    // vertical segment: arrow from B upward toward pulley
    line((6.7, 2.7), (6.7, 3.1),
      stroke: (paint: colT, thickness: 2pt),
      mark: (end: "stealth", fill: colT, scale: 1.1))
    content((7.0, 2.9), text(size: 14pt, fill: colT, weight: "bold")[T])

    // ---- Frictionless marker ----
    content((0.6, 0.7), text(size: 13pt, fill: rgb("#9aa0aa"),
      style: "italic")[frictionless])

    // ---- Motion arrow under block A (direction of motion) ----
    line((4.2, -0.35), (5.6, -0.35),
      stroke: (paint: rgb("#ffd166"), thickness: 2pt),
      mark: (end: "stealth", fill: rgb("#ffd166"), scale: 1.2))
    content((4.9, -0.85), text(size: 13pt, fill: rgb("#ffd166"))[motion])
  })
]

#v(14pt)

// ---------- Answer choices ----------
#set text(size: 21pt)
#grid(
  columns: (1fr, 1fr),
  column-gutter: 16pt,
  row-gutter: 12pt,
  align: (left, left),

  box(
    width: 100%,
    radius: 8pt,
    inset: 10pt,
    stroke: 1.2pt + rgb("#3a3f4a"),
    fill: rgb("#181b23"),
  )[#text(fill: rgb("#ff4d6d"), weight: "bold")[A)] #h(0.5em) 60 N],

  box(
    width: 100%,
    radius: 8pt,
    inset: 10pt,
    stroke: 1.2pt + rgb("#3a3f4a"),
    fill: rgb("#181b23"),
  )[#text(fill: rgb("#4cc9f0"), weight: "bold")[B)] #h(0.5em) 96 N],

  box(
    width: 100%,
    radius: 8pt,
    inset: 10pt,
    stroke: 1.2pt + rgb("#3a3f4a"),
    fill: rgb("#181b23"),
  )[#text(fill: rgb("#06d6a0"), weight: "bold")[C)] #h(0.5em) 48 N],

  box(
    width: 100%,
    radius: 8pt,
    inset: 10pt,
    stroke: 1.2pt + rgb("#3a3f4a"),
    fill: rgb("#181b23"),
  )[#text(fill: rgb("#ffd166"), weight: "bold")[D)] #h(0.5em) 120 N],
)

#v(16pt)

// ---------- Footer prompt ----------
#align(center)[
  #line(length: 100%, stroke: 1pt + rgb("#3a3f4a"))
  #v(6pt)
  #text(size: 16pt, fill: rgb("#9aa0aa"))[
    Drop your answer in the comments 👇
    #h(1em) #text(fill: rgb("#ff4d6d"))[#sym.arrow] #h(1em)
    Solution posted tomorrow.
  ]
]

