#import "@preview/cetz:0.5.2"

#set page(width: 1080pt, height: 1080pt, margin: 60pt)

#set text(font: "New Computer Modern", size: 22pt)

#set par(justify: true, leading: 0.7em)

A car of mass $m$ travels along a horizontal curved road of radius $r$ at a
constant speed $v$. The road is banked at an angle $theta$ (tilted inward toward
the center of the curve). The road is *frictionless*.

#v(6pt)

*At what speed $v$ can the car safely negotiate the curve without sliding up
or down the bank?*

#v(14pt)

#align(center)[
  #cetz.canvas({
    import cetz.draw: *
    set-style(stroke: black, fill: black, stroke-width: 1.4pt)

    // ---- Banked curve (side view of the tilted road surface) ----
    // Road surface: a tilted rectangle. Bank angle theta tilts the road
    // upward toward the center of the curve.
    let bank-angle = 25deg
    let road-left = -1.0
    let road-right = 5.5
    let road-mid-x = (road-left + road-right) / 2

    // Tilted road surface
    line((road-left, 0), (road-right, 0), stroke: 2.2pt)
    line((road-left, 0), (road-left - 0.5, -0.4))
    line((road-right, 0), (road-right - 0.5, -0.4))
    line((road-left - 0.5, -0.4), (road-right - 0.5, -0.4))

    // Hatching under the road to show it's solid
    for x in range(0, 7) {
      let px = road-left + 0.3 + x * 0.9
      line((px, 0), (px - 0.18, -0.4))
    }

    // ---- Angle theta arc at the bottom-left ----
    // Arc between the road surface (which goes up to the right at angle theta)
    // and the horizontal dashed line.
    content((road-left - 0.6, -0.7),
      text(size: 18pt)[$theta$])
    // The road rises to the right at angle theta from horizontal.

    // ---- Car on the banked road ----
    // Place the car on the tilted road. The car sits on the road and is
    // tilted with the bank. We approximate by drawing it aligned to the road.
    let car-cx = road-mid-x
    let car-cy = 0.6
    let car-w = 1.4
    let car-h = 0.55

    // Car body (rotated)
    let t = bank-angle
    let cos-t = calc.cos(t)
    let sin-t = calc.sin(t)
    // Local rectangle corners relative to center
    let corners = (
      (-car-w/2, -car-h/2),
      ( car-w/2, -car-h/2),
      ( car-w/2,  car-h/2),
      (-car-w/2,  car-h/2),
    )
    let rotated = corners.map(c => (
      car-cx + c.at(0) * cos-t - c.at(1) * sin-t,
      car-cy + c.at(0) * sin-t + c.at(1) * cos-t,
    ))
    line((rotated.at(0), rotated.at(1)), stroke: 1.8pt)
    line((rotated.at(1), rotated.at(2)), stroke: 1.8pt)
    line((rotated.at(2), rotated.at(3)), stroke: 1.8pt)
    line((rotated.at(3), rotated.at(0)), stroke: 1.8pt)

    // Car label
    let label-pt = (
      car-cx + 0 * cos-t - (-car-h/2 + 0.2) * sin-t,
      car-cy + 0 * sin-t + (-car-h/2 + 0.2) * cos-t,
    )
    content(label-pt, text(size: 18pt, weight: "bold")[car, $m$])

    // ---- Force arrows on the car ----
    // Normal force N: perpendicular to road, pointing away from surface
    // (upward-left, since road is tilted up to the right)
    let n-len = 1.6
    let n-dir = (-sin-t, cos-t) // perpendicular to road, into the air
    let n-start = (
      car-cx + 0 * cos-t - (-car-h/2 + 0.1) * sin-t,
      car-cy + 0 * sin-t + (-car-h/2 + 0.1) * cos-t,
    )
    line(n-start,
      (n-start.at(0) + n-dir.at(0) * n-len,
       n-start.at(1) + n-dir.at(1) * n-len),
      mark: (end: "stealth", scale: 1.1))
    let n-label = (
      n-start.at(0) + n-dir.at(0) * (n-len + 0.25),
      n-start.at(1) + n-dir.at(1) * (n-len + 0.25),
    )
    content(n-label, text(size: 18pt)[$N$])

    // Weight mg: straight down from car center
    let g-start = (car-cx, car-cy)
    line(g-start, (g-start.at(0), g-start.at(1) - 1.5),
      mark: (end: "stealth", scale: 1.1))
    content((g-start.at(0) - 0.05, g-start.at(1) - 1.8),
      text(size: 18pt)[$m g$])

    // ---- Center of curve indicator (to the left) ----
    // Horizontal arrow from car showing centripetal direction
    line((car-cx, car-cy + 0.4), (car-cx - 2.0, car-cy + 0.4),
      mark: (end: "stealth", scale: 1.0), stroke: (dash: "dashed"))
    content((car-cx - 1.0, car-cy + 0.7),
      text(size: 14pt)[toward center])

    // ---- Radius label ----
    content((car-cx - 1.0, car-cy + 1.2),
      text(size: 14pt)[radius $r$])

    // ---- v label (velocity into the page, shown as dot with circle) ----
    content((car-cx + 0.3, car-cy + 0.1),
      text(size: 16pt, weight: "bold")[circle(times: 1em)[]])
    content((car-cx + 0.55, car-cy + 0.0),
      text(size: 14pt)[$v$])
  })
]

#v(14pt)

#grid(
  columns: (1fr, 1fr),
  column-gutter: 16pt,
  row-gutter: 12pt,
  [A) #h(0.6em) $v = sqrt(r g)$],
  [B) #h(0.6em) $v = sqrt(r g \/ cos theta)$],
  [C) #h(0.6em) $v = sqrt(r g tan theta)$],
  [D) #h(0.6em) $v = sqrt(r g \/ tan theta)$],
)

