input.contents:
#import "@preview/cetz:0.5.2"

#set page(width: 1080pt, height: 1080pt, margin: 60pt)

#set text(font: "New Computer Modern", size: 22pt)

#set par(justify: true, leading: 0.7em)

A car of mass $m$ travels along a horizontal curved road of radius $r$ at a
constant speed $v$. The road is banked at an angle $theta$ (tilted inward
toward the center of the curve). The road is *frictionless*.

#v(6pt)

*At what speed $v$ can the car safely negotiate the curve without sliding up
or down the bank?*

#v(14pt)

#align(center)[
  #cetz.canvas({
    import cetz.draw: *
    set-style(stroke: black, fill: black, stroke-width: 1.4pt)

    // ---- Banked road surface (tilted upward toward the center, left side) ----
    // The road rises to the LEFT (toward the center of the curve).
    let theta-deg = 25
    let theta = theta-deg * 1deg
    let cos-t = calc.cos(theta)
    let sin-t = calc.sin(theta)

    // Road surface as a tilted thick band.
    // Road goes from (road-right, 0) on the right to (road-left, 0) on the left.
    // The road surface line rises to the LEFT.
    let road-right = 5.5
    let road-left = -1.5

    // Draw road as two parallel lines (top surface and bottom)
    // Top surface
    line((road-right, 0.35), (road-left, 0.35 + 2.0))
    // Bottom surface
    line((road-right, 0), (road-left, 2.0))

    // Hatching under the road
    let n-hatch = 12
    for i in range(n-hatch + 1) {
      let t-fraction = i / n-hatch
      let x-top = road-right + (road-left - road-right) * t-fraction
      let y-top = 0.35 + (0.35 + 2.0 - 0.35) * t-fraction
      let x-bot = road-right + (road-left - road-right) * t-fraction
      let y-bot = 0 + (2.0 - 0) * t-fraction
      // Hatch goes from top surface straight down by 0.4
      line((x-top, y-top), (x-top, y-top - 0.4))
    }

    // ---- Car on the banked road ----
    // The car sits on the top surface. We place it at the midpoint of the road.
    let road-mid-t = 0.55
    let car-x = road-right + (road-left - road-right) * road-mid-t
    let car-y = 0.35 + (0.35 + 2.0 - 0.35) * road-mid-t

    // Car local frame: along road direction and perpendicular to road
    // road-direction unit vector (from right to left along top surface)
    let road-dx = (road-left - road-right) / calc.sqrt(
      calc.pow(road-left - road-right, 2) + calc.pow(2.0, 2)
    )
    let road-dy = 2.0 / calc.sqrt(
      calc.pow(road-left - road-right, 2) + calc.pow(2.0, 2)
    )
    // normal to road (pointing away from road, up and to the right)
    let norm-dx = road-dy
    let norm-dy = -road-dx

    let car-len = 1.6
    let car-h = 0.55

    // Car corners in local frame (relative to center)
    let local-corners = (
      (-car-len/2, -car-h/2),
      ( car-len/2, -car-h/2),
      ( car-len/2,  car-h/2),
      (-car-len/2,  car-h/2),
    )
    let car-corners = local-corners.map(c => (
      car-x + c.at(0) * road-dx + c.at(1) * norm-dx,
      car-y + c.at(0) * road-dy + c.at(1) * norm-dy,
    ))
    for i in range(car-corners.len()) {
      let p1 = car-corners.at(i)
      let p2 = car-corners.at(calc.rem(i + 1, car-corners.len()))
      line(p1, p2, stroke: 1.8pt)
    }

    // ---- Force arrows on the car ----
    // Normal force N: perpendicular to road, pointing away from surface
    let n-len = 1.4
    let n-start = (car-x - norm-dx * car-h/2 * 0.5, car-y - norm-dy * car-h/2 * 0.5)
    line(n-start,
      (n-start.at(0) + norm-dx * n-len,
       n-start.at(1) + norm-dy * n-len),
      mark: (end: "stealth", scale: 1.1))
    content((n-start.at(0) + norm-dx * (n-len + 0.3),
             n-start.at(1) + norm-dy * (n-len + 0.3)),
      text(size: 20pt)[$N$])

    // Weight mg: straight down from car center
    line((car-x, car-y), (car-x, car-y - 1.6),
      mark: (end: "stealth", scale: 1.1))
    content((car-x - 0.05, car-y - 1.9),
      text(size: 20pt)[$m g$])

    // ---- Angle theta arc at the bottom of the bank ----
    // Show the bank angle between the road surface and the horizontal.
    // At the right end of the road, draw a horizontal dashed line and arc.
    let arc-cx = road-right + 0.6
    let arc-cy = 0
    // Arc from horizontal (pointing left from arc center) to road direction
    // Horizontal direction from arc-cx,arc-cy goes to (arc-cx - 1, arc-cy)
    // Road direction from arc-cx,arc-cy: along (road-left - road-right, 2.0) normalized
    // Just draw an arc from (-0.5, 0) to (some point along the road direction at same radius)
    let arc-r = 0.8
    let p1 = (arc-cx - arc-r, arc-cy)
    // Angle of road surface relative to horizontal at the road's right end
    let road-angle = calc.atan2(2.0, road-left - road-right)
    let p2-x = arc-cx + arc-r * calc.cos(road-angle + calc.pi)
    let p2-y = arc-cy + arc-r * calc.sin(road-angle + calc.pi)
    // Actually, draw arc between two points
    cetz.draw.arc(
      (arc-cx, arc-cy),
      radius: arc-r,
      start: 180deg,
      stop: 180deg + theta,
      stroke: 1.4pt,
    )

    // Label theta
    content((arc-cx - 1.4, -0.5),
      text(size: 20pt)[$theta$])

    // ---- Horizontal reference dashed line ----
    line((road-right + 0.05, 0.35), (road-right + 1.3, 0.35),
      stroke: (dash: "dashed"))

    // ---- Car label ----
    content((car-x + 0.4, car-y + 0.4),
      text(size: 18pt)[car, $m$])

    // ---- Centripetal arrow (horizontal, pointing left, toward center) ----
    let cent-y = car-y - 2.6
    let cent-x-start = car-x + 0.5
    let cent-x-end = cent-x-start - 3.5
    line((cent-x-start, cent-y), (cent-x-end, cent-y),
      mark: (end: "stealth", scale: 1.1), stroke: (dash: "dashed"))
    content(((cent-x-start + cent-x-end) / 2, cent-y - 0.3),
      text(size: 16pt)[toward center, radius $r$])

    // ---- Velocity label (into the page, shown as ⊗ symbol) ----
    content((car-x + 0.1, car-y - 0.2),
      text(size: 22pt)[$circle$])
    content((car-x + 0.45, car-y - 0.3),
      text(size: 16pt)[$v$])
  })
]

#v(14pt)

#grid(
  columns: (1fr, 1fr),
  column-gutter: 16pt,
  row-gutter: 12pt,
  [A) #h(0.6em) $v = sqrt(r g)$],
  [B) #h(0.6em) $v = sqrt(r g \/ cos theta)$],
  [C) #h(0.6em) $v = sqrt(r g tan theta)$],
  [D) #h(0.6em) $v = sqrt(r g \/ tan theta)$],
)

