#align(center)[
  #cetz.canvas({
    import cetz.draw: *
    set-style(stroke: black, fill: black, stroke-width: 1.4pt)

    // ---- Geometry ----
    // Banked road: rises to the LEFT (toward center of curve)
    let theta = 22deg
    let cos-t = calc.cos(theta)
    let sin-t = calc.sin(theta)

    // Road as a tilted rectangle band.
    // The "downhill" direction (away from center) is along the +x axis.
    // The "uphill" direction (toward center) is up and to the left.
    let road-width = 0.35 // thickness of road band
    let road-len = 7.0    // length along the slope

    // Unit vector along the road (from uphill end to downhill end, i.e., right)
    let ux = cos-t
    let uy = -sin-t
    // Unit vector perpendicular to road (out of surface, into the air)
    let nx = sin-t
    let ny = cos-t

    // Define four corners of the road band
    let uphill-top = (-road-len/2 * ux + nx * road-width,
                      -road-len/2 * uy + ny * road-width)
    let uphill-bot = (-road-len/2 * ux - nx * road-width,
                      -road-len/2 * uy - ny * road-width)
    let downhill-top = ( road-len/2 * ux + nx * road-width,
                          road-len/2 * uy + ny * road-width)
    let downhill-bot = ( road-len/2 * ux - nx * road-width,
                          road-len/2 * uy - ny * road-width)

    // Hatching under the road (vertical lines from bottom surface down)
    let n-hatch = 14
    for i in range(n-hatch + 1) {
      let s = i / n-hatch // 0 at uphill, 1 at downhill
      // point on bottom surface
      let px = (1 - s) * uphill-bot.at(0) + s * downhill-bot.at(0)
      let py = (1 - s) * uphill-bot.at(1) + s * downhill-bot.at(1)
      // hatch line: from bottom surface straight down by 0.4
      line((px, py), (px, py - 0.4))
    }

    // Draw the two long sides of the road band
    line(uphill-top, downhill-top, stroke: 2.0pt)
    line(uphill-bot, downhill-bot, stroke: 1.6pt)
    // End caps
    line(uphill-top, uphill-bot, stroke: 1.6pt)
    line(downhill-top, downhill-bot, stroke: 1.6pt)

    // ---- Car on the road (sits on top surface, oriented along the slope) ----
    let car-center-s = 0.4 // 40% of the way from uphill to downhill
    let car-cx = (1 - car-center-s) * uphill-top.at(0)
               + car-center-s * downhill-top.at(0)
    let car-cy = (1 - car-center-s) * uphill-top.at(1)
               + car-center-s * downhill-top.at(1)
    // Lift car a bit so it sits ON the top surface
    let car-cx = car-cx + nx * 0.02
    let car-cy = car-cy + ny * 0.02

    let car-len = 1.6
    let car-h = 0.6

    // Car corners in world frame
    let car-local = (
      (-car-len/2, -car-h/2),
      ( car-len/2, -car-h/2),
      ( car-len/2,  car-h/2),
      (-car-len/2,  car-h/2),
    )
    let car-corners = car-local.map(c => (
      car-cx + c.at(0) * ux + c.at(1) * nx,
      car-cy + c.at(0) * uy + c.at(1) * ny,
    ))
    for i in range(car-corners.len()) {
      let p1 = car-corners.at(i)
      let p2 = car-corners.at(calc.rem(i + 1, car-corners.len()))
      line(p1, p2, stroke: 1.8pt)
    }

    // ---- Force arrows on the car ----
    // Normal force N: perpendicular to road, away from surface
    let n-len = 1.5
    // Start: at center of car bottom edge
    let n-start = (
      car-cx + (-car-len/2 * 0.3) * ux + (-car-h/2) * nx,
      car-cy + (-car-len/2 * 0.3) * uy + (-car-h/2) * ny,
    )
    line(n-start,
      (n-start.at(0) + nx * n-len,
       n-start.at(1) + ny * n-len),
      mark: (end: "stealth", scale: 1.1))
    content((n-start.at(0) + nx * (n-len + 0.35),
             n-start.at(1) + ny * (n-len + 0.35)),
      text(size: 22pt)[$N$])

    // Weight mg: straight down from car center
    line((car-cx, car-cy), (car-cx, car-cy - 1.8),
      mark: (end: "stealth", scale: 1.1))
    content((car-cx + 0.1, car-cy - 2.1),
      text(size: 22pt)[$m g$])

    // ---- Centripetal arrow (horizontal, pointing left toward center) ----
    let cent-y = car-cy - 2.8
    let cent-x-end = car-cx - 4.5
    let cent-x-start = car-cx - 0.2
    line((cent-x-start, cent-y), (cent-x-end, cent-y),
      mark: (end: "stealth", scale: 1.1), stroke: (dash: "dashed"))
    content(((cent-x-start + cent-x-end) / 2, cent-y - 0.35),
      text(size: 16pt)[toward center of curve])

    // ---- Radius r label ----
    content((cent-x-end - 0.4, cent-y + 0.35),
      text(size: 16pt)[radius $r$])

    // ---- Angle theta arc at the uphill end ----
    // Arc between the road's downhill direction (along +x from uphill end)
    // and the horizontal direction. The road goes from uphill end downhill
    // at angle theta BELOW the horizontal.
    let arc-cx = uphill-bot.at(0) - 0.3
    let arc-cy = uphill-bot.at(1) - 0.3
    let arc-r = 1.0
