      radius: arc-r,
      start: 0deg,
      stop: -theta,
      stroke: 1.4pt,
    )
    content((arc-cx + 0.9, arc-cy - 0.7),
      text(size: 22pt)[$theta$])

    // ---- Velocity label (⊗ into the page) on top of the car ----
    content((car-cx - 0.1, car-cy - 0.1),
      text(size: 24pt, weight: "bold")[$circle$])
    content((car-cx + 0.35, car-cy - 0.3),
      text(size: 18pt)[$v$])

    // ---- "car, m" label above the car ----
    content((car-cx - 0.2, car-cy + 0.7),
      text(size: 16pt)[car, mass $m$])
  })
