#import "@preview/cetz:0.5.2"

#set page(width: 1080pt, height: 1080pt, margin: 60pt)

#set text(font: "New Computer Modern", size: 22pt)

#set par(justify: true, leading: 0.7em)

A car of mass $m$ travels along a horizontal curved road of radius $r$ at a
constant speed $v$. The road is banked at an angle $theta$ (tilted inward
toward the center of the curve). The road is *frictionless*.

#v(6pt)

*At what speed $v$ can the car safely negotiate the curve without sliding up
or down the bank?*

#v(14pt)

#align(center)[
  #cetz.canvas({
    import cetz.draw: *
    set-style(stroke: black, fill: black, stroke-width: 1.4pt)

    // === Banked road (side view) ===
    // The road tilts UP to the LEFT (toward center of curve).
    // Use a slant of about 22 degrees.
    let theta = 22deg
    let ct = calc.cos(theta)
    let st = calc.sin(theta)

    // ---- Road (a tilted band) ----
    // Two parallel lines (top and bottom of road) plus end caps and hatching.
    // Up direction perpendicular to road: (sin t, cos t)
    // Along direction of road from uphill to downhill: (cos t, -sin t)
    // Let's compute the four corners using straight typst math.
    let band-half-len = 4.0
    let band-thick = 0.35

    // uphill (left, top) corner
    let uxt = calc.mul(calc.neg(band-half-len), ct) +
              calc.mul(band-thick, st) // = -L cos + T sin
    let uyt = calc.mul(calc.neg(band-half-len), st) +
              calc.mul(band-thick, ct) // = -L sin + T cos  (positive y)
    let uxb = calc.mul(calc.neg(band-half-len), ct) +
              calc.mul(calc.neg(band-thick), st)
    let uyb = calc.mul(calc.neg(band-half-len), st) +
              calc.mul(calc.neg(band-thick), ct)
    let dxt = calc.mul(band-half-len, ct) +
              calc.mul(band-thick, st)
    let dyt = calc.mul(band-half-len, st) +
              calc.mul(band-thick, ct)
    let dxb = calc.mul(band-half-len, ct) +
              calc.mul(calc.neg(band-thick), st)
    let dyb = calc.mul(band-half-len, st) +
              calc.mul(calc.neg(band-thick), ct)

    // Hatching: vertical lines from the bottom edge of the road
    let n-hatch = 12
    for i in range(n-hatch + 1) {
      let s = calc.div(i, n-hatch) // 0..1 along the road
      let bx = calc.add(
        calc.mul(calc.sub(1.0, s), uxb),
        calc.mul(s, dxb),
      )
      let by = calc.add(
        calc.mul(calc.sub(1.0, s), uyb),
        calc.mul(s, dyb),
      )
      line((bx, by), (bx, by - 0.4))
    }

    // Draw band edges
    line((uxt, uyt), (dxt, dyt), stroke: 2.0pt) // top
    line((uxb, uyb), (dxb, dyb))                 // bottom
    line((uxt, uyt), (uxb, uyb))                 // uphill end cap
    line((dxt, dyt), (dxb, dyb))                 // downhill end cap

    // ---- Angle theta arc at the uphill end ----
    // Place an arc near the uphill-bottom corner.
    let arc-cx = calc.add(uxb, calc.mul(calc.neg(0.3), ct))
    let arc-cy = calc.add(uyb, calc.mul(calc.neg(0.3), st))
    let arc-r = 1.0
    cetz.draw.arc(
      (arc-cx, arc-cy),
      radius: arc-r,
      start: 180deg,
      stop: calc.add(180deg, theta),
      stroke: 1.4pt,
    )
    content((calc.sub(arc-cx, 0.3), calc.sub(arc-cy, 0.9)),
      text(size: 22pt)[$theta$])

    // ---- Car on the top surface ----
    // Sits about 35% of the way from uphill to downhill along top edge.
    let s-car = 0.35
    let cx = calc.add(
      calc.mul(calc.sub(1.0, s-car), uxt),
      calc.mul(s-car, dxt),
    )
    let cy = calc.add(
      calc.mul(calc.sub(1.0, s-car), uyt),
      calc.mul(s-car, dyt),
    )
    // Slight offset along the normal so the car sits ON the surface
    let off = 0.01
    cx = calc.add(cx, calc.mul(st, off))
    cy = calc.add(cy, calc.mul(ct, off))

    // Car rectangle in world frame, oriented with the road
    let car-len-half = 0.8
    let car-h-half = 0.3
    // Local (along, normal) -> World
    let c0-x = calc.add(cx,
      calc.add(
        calc.mul(calc.neg(car-len-half), ct),
        calc.mul(calc.neg(car-h-half), calc.neg(st))
      )
    )
    let c0-y = calc.add(cy,
      calc.add(
        calc.mul(calc.neg(car-len-half), calc.neg(st)),
        calc.mul(calc.neg(car-h-half), ct)
      )
    )
    let c1-x = calc.add(cx,
      calc.add(
        calc.mul(car-len-half, ct),
        calc.mul(calc.neg(car-h-half), calc.neg(st))
      )
    )
    let c1-y = calc.add(cy,
      calc.add(
        calc.mul(car-len-half, calc.neg(st)),
        calc.mul(calc.neg(car-h-half), ct)
      )
    )
    let c2-x = calc.add(cx,
      calc.add(
        calc.mul(car-len-half, ct),
        calc.mul(car-h-half, calc.neg(st))
      )
    )
    let c2-y = calc.add(cy,
      calc.add(
        calc.mul(car-len-half, calc.neg(st)),
        calc.mul(car-h-half, ct)
      )
    )
    let c3-x = calc.add(cx,
      calc.add(
        calc.mul(calc.neg(car-len-half), ct),
        calc.mul(car-h-half, calc.neg(st))
      )
    )
    let c3-y = calc.add(cy,
      calc.add(
        calc.mul(calc.neg(car-len-half), calc.neg(st)),
        calc.mul(car-h-half, ct)
      )
    )
    line((c0-x, c0-y), (c1-x, c1-y), stroke: 1.8pt)
    line((c1-x, c1-y), (c2-x, c2-y), stroke: 1.8pt)
    line((c2-x, c2-y), (c3-x, c3-y), stroke: 1.8pt)
    line((c3-x, c3-y), (c0-x, c0-y), stroke: 1.8pt)

    // ---- Force arrows ----
    // Normal force N: perpendicular to road, away from surface
    let n-len = 1.6
    let n-end-x = calc.add(cx, calc.mul(st, n-len))
    let n-end-y = calc.add(cy, calc.mul(ct, n-len))
    line((cx, cy), (n-end-x, n-end-y),
      mark: (end: "stealth", scale: 1.1))
    content(
      (calc.add(n-end-x, calc.mul(st, 0.3)),
       calc.add(n-end-y, calc.mul(ct, 0.3))),
      text(size: 22pt)[$N$])

    // Weight mg: straight down from car center
    let g-end-y = calc.sub(cy, 2.0)
    line((cx, cy), (cx, g-end-y),
      mark: (end: "stealth", scale: 1.1))
    content((calc.add(cx, 0.1), calc.sub(g-end-y, 0.3)),
      text(size: 22pt)[$m g$])

    // ---- Velocity label (⊗ into page) on the car ----
    content((calc.sub(cx, 0.05), calc.sub(cy, 0.2)),
      text(size: 26pt, weight: "bold")[$circle$])
    content((calc.add(cx, 0.4), calc.sub(cy, 0.3)),
      text(size: 18pt)[$v$])

    // ---- "car, mass m" label above the car ----
    content((calc.sub(cx, 0.2), calc.add(cy, 0.95)),
      text(size: 16pt)[car, mass $m$])

    // ---- Centripetal arrow ----
    // Place a horizontal arrow below the road pointing left (toward center)
    let cent-y = calc.sub(uyb, 0.9) // below the road's bottom
    let cent-x-end = calc.sub(cx, 4.5)
    let cent-x-start = calc.add(cx, 0.2)
    line((cent-x-start, cent-y), (cent-x-end, cent-y),
      mark: (end: "stealth", scale: 1.1), stroke: (dash: "dashed"))
    content(
      (calc.div(calc.add(cent-x-start, cent-x-end), 2),
       calc.sub(cent-y, 0.35)),
      text(size: 16pt)[toward center of curve])

    // ---- Radius r label ----
    content(
      (calc.sub(cent-x-end, 0.3), calc.add(cent-y, 0.4)),
      text(size: 16pt)[radius $r$])
  })
]

#v(14pt)

#grid(
