input.contents:
#import "@preview/cetz:0.5.2"

#set page(width: 1080pt, height: 1080pt, margin: 60pt)

#set text(font: "New Computer Modern", size: 22pt)

#set par(justify: true, leading: 0.7em)

A car of mass $m$ travels along a horizontal curved road of radius $r$ at a
constant speed $v$. The road is banked at an angle $theta$ (tilted inward
toward the center of the curve). The road is *frictionless*.

#v(6pt)

*At what speed $v$ can the car safely negotiate the curve without sliding up
or down the bank?*

#v(14pt)

#align(center)[
  #cetz.canvas({
    import cetz.draw: *
    set-style(stroke: black, fill: black, stroke-width: 1.4pt)

    // === Banked road, side view ===
    // Choose a 22-degree bank, going from downhill (right) to uphill (left).
    // Hard-coded angles via scalar constants — avoid trig + rotation pitfalls
    // by drawing all positions directly.

    // Top surface of the road: passes through the points
    //   (-3.6, 1.45) (uphill end, top)
    // and ( 4.0, 0.0)  (downhill end, top), so the slope rises to the left.
    // Bottom surface: parallel, 0.35 below.
    let A = (-3.6, 1.45)        // uphill, top
    let B = ( 4.0, 0.0)         // downhill, top
    let C = (-3.6, 1.45 - 0.35) // uphill, bottom
    let D = ( 4.0, 0.0 - 0.35)  // downhill, bottom

    // Hatching below the road surface (vertical ticks)
    let n-hatch = 12
    for i in range(n-hatch + 1) {
      let s = i / n-hatch
      let bx = (1 - s) * C.at(0) + s * D.at(0)
      let by = (1 - s) * C.at(1) + s * D.at(1)
      line((bx, by), (bx, by - 0.4))
    }

    // Draw the band: top, bottom, two end caps
    line(A, B, stroke: 2.0pt)
    line(C, D)
    line(A, C)
    line(B, D)

    // ---- Angle theta arc at the uphill end ----
    // The road surface at the uphill end goes from A down to B direction.
    // Place arc just below-left of the uphill end, between the
    // horizontal and the road-direction.
    let arc-cx = -4.4
    let arc-cy = 0.9
    let arc-r = 0.9
    // Horizontal points right (angle 0). The road surface at this end
    // angles DOWN to the right (i.e., its tangent points +x at 360-22 = -22 deg).
    cetz.draw.arc(
      (arc-cx, arc-cy),
      radius: arc-r,
      start: 360deg - 22deg,
      stop: 360deg,
      stroke: 1.4pt,
    )
    content((-4.4, 0.45),
      text(size: 22pt)[$theta$])

    // ---- Car on the road (sits on top surface, oriented along the slope) ----
    // Use a 60/40 split on the top edge.
    let s-car = 0.4
    let cx = (1 - s-car) * A.at(0) + s-car * B.at(0)
    let cy = (1 - s-car) * A.at(1) + s-car * B.at(1)
    // Lift slightly along the surface normal so the car sits ON the top line.
    let off = 0.02
    // The top edge unit direction (downhill): from A to B.
    let ab-dx = B.at(0) - A.at(0)
    let ab-dy = B.at(1) - A.at(1)
    let ab-len = calc.sqrt(ab-dx * ab-dx + ab-dy * ab-dy)
    let tx = ab-dx / ab-len
    let ty = ab-dy / ab-len
    // Surface normal (perpendicular, pointing up-right): (ty, -tx) flipped
    let nx = ty
    let ny = -tx
    cx = cx + nx * off
    cy = cy + ny * off

    // Car rectangle, oriented along the slope
    let car-len-half = 0.85
    let car-h-half = 0.32
    let c0 = (cx + (-car-len-half) * tx + (-car-h-half) * nx,
              cy + (-car-len-half) * ty + (-car-h-half) * ny)
    let c1 = (cx + ( car-len-half) * tx + (-car-h-half) * nx,
              cy + ( car-len-half) * ty + (-car-h-half) * ny)
    let c2 = (cx + ( car-len-half) * tx + ( car-h-half) * nx,
              cy + ( car-len-half) * ty + ( car-h-half) * ny)
    let c3 = (cx + (-car-len-half) * tx + ( car-h-half) * nx,
              cy + (-car-len-half) * ty + ( car-h-half) * ny)
    line(c0, c1, stroke: 1.8pt)
    line(c1, c2, stroke: 1.8pt)
    line(c2, c3, stroke: 1.8pt)
    line(c3, c0, stroke: 1.8pt)

    // ---- Force arrows ----
    // Normal force N: perpendicular to surface, pointing up-right
    let n-len = 1.7
    let n-end = (cx + nx * n-len, cy + ny * n-len)
    line((cx, cy), n-end, mark: (end: "stealth", scale: 1.1))
    content((n-end.at(0) + nx * 0.3, n-end.at(1) + ny * 0.3),
      text(size: 22pt)[$N$])

    // Weight mg: straight down from car center
    let g-end = (cx, cy - 2.0)
    line((cx, cy), g-end, mark: (end: "stealth", scale: 1.1))
    content((cx + 0.1, g-end.at(1) - 0.3),
      text(size: 22pt)[$m g$])

    // ---- Velocity indicator (⊗ symbol on the car roof) ----
    content((cx - 0.15, cy - 0.2),
      text(size: 26pt, weight: "bold")[$circle$])
    content((cx + 0.35, cy - 0.35),
      text(size: 18pt)[$v$])

    // ---- "car, mass m" label above the car ----
    content((cx - 0.4, cy + 1.0),
      text(size: 16pt)[car, mass $m$])

    // ---- Centripetal arrow (horizontal, pointing left toward center) ----
    let cent-y = cy - 2.6
    let cent-x-start = cx + 0.5
    let cent-x-end = cx - 4.5
    line((cent-x-start, cent-y), (cent-x-end, cent-y),
      mark: (end: "stealth", scale: 1.1), stroke: (dash: "dashed"))
    content(((cent-x-start + cent-x-end) / 2, cent-y - 0.35),
      text(size: 16pt)[toward center of curve])

    // ---- Radius r label ----
    content((cent-x-end - 0.2, cent-y + 0.4),
      text(size: 16pt)[radius $r$])
  })
]

#v(14pt)

#grid(
  columns: (1fr, 1fr),
  column-gutter: 16pt,
  row-gutter: 12pt,
  [A) #h(0.6em) $v = sqrt(r g)$],
  [B) #h(0.6em) $v = sqrt(r g \/ cos theta)$],
  [C) #h(0.6em) $v = sqrt(r g tan theta)$],
  [D) #h(0.6em) $v = sqrt(r g \/ tan theta)$],
)

