#import "@preview/cetz:0.5.2"

#set page(width: 1080pt, height: 1080pt, margin: 60pt)

#set text(font: "New Computer Modern", size: 20pt)

#set par(justify: true, leading: 0.7em)

A ball travels along a helical path downward at *constant speed*, as shown
in the figure below.

#v(6pt)

*Which of the following arrows correctly shows the direction of the ball's
acceleration at the marked instant?*

#v(8pt)

// === Main helix diagram (large, showing the helical path) ===
#align(center)[
  #cetz.canvas({
    import cetz.draw: *
    set-style(stroke: black, fill: black, stroke-width: 1.4pt)

    // ---- Helix (drawn in 3D-perspective view) ----
    // The helix is parametrized in 3D: (r cos t, r sin t, -k t)
    // We project to 2D using an oblique projection:
    //   x_screen = x + 0.4 * z   (slight 3D feel, axis going into-page-down)
    //   y_screen = y + 0.0 * z   (no vertical foreshortening)
    let r = 2.2
    let k = 0.6 // vertical drop per radian
    let n-turns = 1.6
    let n-segs = 80
    let proj-x = (x, z) => x + 0.35 * z
    let proj-y = (y, z) => y + 0.10 * z

    // Draw the helix
    let last = (1.0, 0.0)
    for i in range(n-segs + 1) {
      let t = i / n-segs * n-turns * 2 * calc.pi
      let x = r * calc.cos(t)
      let y = r * calc.sin(t)
      let z = -k * t
      let sx = proj-x(x, z)
      let sy = proj-y(y, z)
      if i > 0 {
        line(last, (sx, sy))
      }
      last = (sx, sy)
    }

    // ---- Vertical axis (the central axis of the helix) ----
    let axis-top-z = 1.5
    let axis-bot-z = -k * n-turns * 2 * calc.pi - 0.3
    line(
      (proj-x(0, axis-top-z), proj-y(0, axis-top-z)),
      (proj-x(0, axis-bot-z), proj-y(0, axis-bot-z)),
      stroke: (dash: "dashed", dasharray: (4pt, 3pt))
    )

    // ---- The ball at the marked instant ----
    // Place it about 2/3 of the way down. t = 0.66 * n-turns * 2pi.
    let t-ball = 0.62 * n-turns * 2 * calc.pi
    let xb = r * calc.cos(t-ball)
    let yb = r * calc.sin(t-ball)
    let zb = -k * t-ball
    let sx-b = proj-x(xb, zb)
    let sy-b = proj-y(yb, zb)
    // Ball as a filled circle
    circle((sx-b, sy-b), radius: 0.22, fill: black)
    // Label "ball"
    content((sx-b + 0.55, sy-b + 0.25),
      text(size: 18pt)[ball])

    // ---- Velocity arrow (tangent to helix, pointing in direction of motion) ----
    // Approximate tangent using a small step from t-ball
    let dt = 0.05
    let xt = r * calc.cos(t-ball + dt)
    let yt = r * calc.sin(t-ball + dt)
    let zt = -k * (t-ball + dt)
    let sx-t = proj-x(xt, zt)
    let sy-t = proj-y(yt, zt)
    let vdx = sx-t - sx-b
    let vdy = sy-t - sy-b
    let v-len = calc.sqrt(vdx * vdx + vdy * vdy)
    let vux = vdx / v-len
    let vuy = vdy / v-len
    let v-arrow-len = 1.8
    line((sx-b, sy-b),
      (sx-b + vux * v-arrow-len, sy-b + vuy * v-arrow-len),
      mark: (end: "stealth", scale: 1.0), stroke: 1.6pt)
    content((sx-b + vux * (v-arrow-len + 0.4),
             sy-b + vuy * (v-arrow-len + 0.4)),
      text(size: 20pt)[$bold(v)$])

    // ---- Label for the helix ----
    content((-3.6, 4.0),
      text(size: 18pt)[helical path])
  })
]

#v(10pt)

// === Four small option diagrams showing different candidate accelerations ===
#align(center)[
  #grid(
    columns: (1fr, 1fr),
    column-gutter: 20pt,
    row-gutter: 14pt,
    [
      #cetz.canvas({
        import cetz.draw: *
        set-style(stroke: black, fill: black, stroke-width: 1.4pt)
        // Simplified view: ball + arrow option A: along velocity (tangent)
        // Draw a small helix arc fragment and the ball.
        // Top-down semicircle in 2D, ball at the side, arrow tangent to motion
        let cx = 0
        let cy = 0
        let r = 1.2
        // Helix fragment as a curved arc going behind
        cetz.draw.arc((cx, cy), radius: r, start: 30deg, stop: 200deg)
        // Vertical axis (dashed)
        line((cx, cy - 1.6), (cx, cy + 1.6),
          stroke: (dash: "dashed"))
        // Ball position on the helix (about 60deg from top)
        let ball-angle = 120deg
        let bx = cx + r * calc.cos(ball-angle)
        let by = cy + r * calc.sin(ball-angle)
        circle((bx, by), radius: 0.18, fill: black)
        // Velocity direction: tangent, downward-ish
        let tx = -calc.sin(ball-angle)
        let ty = calc.cos(ball-angle)
        // Combine with downward drop (helix moves down)
        let vx = tx
        let vy = ty - 0.4
        let vl = calc.sqrt(vx * vx + vy * vy)
        vx = vx / vl
        vy = vy / vl
        let arrow-len = 1.4
        line((bx, by),
          (bx + vx * arrow-len, by + vy * arrow-len),
          mark: (end: "stealth", scale: 1.0))
      })
    ],
    [
      #cetz.canvas({
        import cetz.draw: *
        set-style(stroke: black, fill: black, stroke-width: 1.4pt)
        let cx = 0
        let cy = 0
        let r = 1.2
        cetz.draw.arc((cx, cy), radius: r, start: 30deg, stop: 200deg)
        line((cx, cy - 1.6), (cx, cy + 1.6),
          stroke: (dash: "dashed"))
        let ball-angle = 120deg
        let bx = cx + r * calc.cos(ball-angle)
        let by = cy + r * calc.sin(ball-angle)
        circle((bx, by), radius: 0.18, fill: black)
        // Option B: acceleration toward axis but tilted up (not horizontal)
        let ax = cx - bx
        let ay = cy - by
        // Add upward tilt
        ay = ay + 0.8
        let al = calc.sqrt(ax * ax + ay * ay)
        ax = ax / al
        ay = ay / al
        let arrow-len = 1.4
        line((bx, by),
          (bx + ax * arrow-len, by + ay * arrow-len),
          mark: (end: "stealth", scale: 1.0))
      })
    ],
    [
      #cetz.canvas({
        import cetz.draw: *
        set-style(stroke: black, fill: black, stroke-width: 1.4pt)
        let cx = 0
        let cy = 0
        let r = 1.2
        cetz.draw.arc((cx, cy), radius: r, start: 30deg, stop: 200deg)
        line((cx, cy - 1.6), (cx, cy + 1.6),
          stroke: (dash: "dashed"))
        let ball-angle = 120deg
        let bx = cx + r * calc.cos(ball-angle)
        let by = cy + r * calc.sin(ball-angle)
        circle((bx, by), radius: 0.18, fill: black)
        // Option C: acceleration horizontal, pointing toward axis
        let ax = cx - bx
        let ay = 0
        let al = calc.sqrt(ax * ax + ay * ay)
        if al > 0 {
          ax = ax / al
          ay = ay / al
        }
        let arrow-len = 1.4
        line((bx, by),
          (bx + ax * arrow-len, by + ay * arrow-len),
          mark: (end: "stealth", scale: 1.0))
      })
    ],
    [
      #cetz.canvas({
        import cetz.draw: *
        set-style(stroke: black, fill: black, stroke-width: 1.4pt)
        let cx = 0
        let cy = 0
        let r = 1.2
        cetz.draw.arc((cx, cy), radius: r, start: 30deg, stop: 200deg)
        line((cx, cy - 1.6), (cx, cy + 1.6),
          stroke: (dash: "dashed"))
        let ball-angle = 120deg
        let bx = cx + r * calc.cos(ball-angle)
        let by = cy + r * calc.sin(ball-angle)
        circle((bx, by), radius: 0.18, fill: black)
        // Option D: acceleration has both inward AND downward components
        let ax = cx - bx
        let ay = cy - by - 0.6
        let al = calc.sqrt(ax * ax + ay * ay)
        ax = ax / al
        ay = ay / al
        let arrow-len = 1.4
        line((bx, by),
          (bx + ax * arrow-len, by + ay * arrow-len),
          mark: (end: "stealth", scale: 1.0))
      })
    ],
  )
]

#v(4pt)

#grid(
  columns: (1fr, 1fr),
  column-gutter: 16pt,
  row-gutter: 8pt,
  align: (left, left),
  [A) #h(0.6em) arrow tangent to the helix],
  [B) #h(0.6em) toward the axis, tilted upward],
  [C) #h(0.6em) horizontal, pointing toward the axis],
  [D) #h(0.6em) toward the axis, tilted downward],
)

